class ReportClassificationTests(unittest.TestCase):
    def report(self, statuses, **metadata):
        test = {\"status\": \"expected\", \"expectedStatus\": \"passed\",
                \"results\": [{\"status\": status, \"retry\": i, \"duration\": 10}
                            for i, status in enumerate(statuses)]}
        test.update(metadata)
        return {\"specs\": [{\"title\": SCENARIOS[0] + \": example\", \"tests\": [test]}]}

    def test_single_status_and_missing_evidence(self):
        for status in (\"passed\", \"failed\", \"timedOut\", \"interrupted\", \"skipped\"):
            with self.subTest(status=status):
                result = classify_report(self.report([status]))
                self.assertEqual(result[\"scenarios\"][SCENARIOS[0]], status)
                self.assertEqual(sum(result[\"scenario_counts\"].values()), 4)
        for report in ({}, {\"specs\": [{\"title\": SCENARIOS[0], \"tests\": []}]},
                       self.report([]), self.report([], results=None)):
            expected = \"failed\" if report == self.report([], results=None) else \"unexecuted\"
            self.assertEqual(classify_report(report)[\"scenarios\"][SCENARIOS[0]], expected)
        report = self.report([])
        del report[\"specs\"][0][\"tests\"][0][\"results\"]
        self.assertEqual(classify_report(report)[\"scenarios\"][SCENARIOS[0]], \"unexecuted\")

    def test_invalid_status_and_expectation_cannot_pass(self):
        for report in (self.report([None]), self.report([\"unknown\"]),
                       self.report([\"passed\"], status=\"flaky\"),
                       self.report([\"passed\"], expectedStatus=\"failed\"),
                       self.report([\"passed\"], expectedStatus=None),
                       self.report([], results={}), self.report([], results=[None])):
            result = classify_report(report)
            self.assertEqual(result[\"scenarios\"][SCENARIOS[0]], \"failed\")
            self.assertTrue(result[\"classification_diagnostics\"][SCENARIOS[0]])
        report = self.report([\"passed\"])
        del report[\"specs\"][0][\"tests\"][0][\"expectedStatus\"]
        self.assertEqual(classify_report(report)[\"scenarios\"][SCENARIOS[0]], \"failed\")

    def test_mixed_attempts_and_nested_duplicates_are_order_independent(self):
        for status in (\"failed\", \"timedOut\", \"interrupted\", \"skipped\"):
            for attempts in ([status, \"passed\"], [\"passed\", status]):
                result = classify_report(self.report(attempts))
                self.assertEqual(result[\"scenarios\"][SCENARIOS[0]], status)
                self.assertEqual(result[\"raw_scenarios\"][SCENARIOS[0]][0][\"results\"],
                                 self.report(attempts)[\"specs\"][0][\"tests\"][0][\"results\"])
        for other, expected in ((self.report([\"timedOut\"]), \"timedOut\"),
                                (self.report([]), \"unexecuted\")):
            for children in ([self.report([\"passed\"]), other],
                             [other, self.report([\"passed\"]) ]):
                result = classify_report({\"suites\": children})
                self.assertEqual(result[\"scenarios\"][SCENARIOS[0]], expected)
                self.assertEqual(len(result[\"raw_scenarios\"][SCENARIOS[0]]), 2)
            tests = self.report([\"passed\"])[\"specs\"][0][\"tests\"] + other[\"specs\"][0][\"tests\"]
            report = {\"specs\": [{\"title\": SCENARIOS[0], \"tests\": tests}]}
            self.assertEqual(classify_report(report)[\"scenarios\"][SCENARIOS[0]], expected)

    def test_run_gate(self):
        for exit_code, status, present in ((0, \"passed\", True), (1, \"passed\", True),
                                           (0, \"skipped\", True), (0, \"timedOut\", True),
                                           (0, \"passed\", False), (0, None, True)):
            with self.subTest(exit_code=exit_code, status=status, present=present):
