                        accepted = exit_code == 0 and status == \"passed\" and present
                        self.assertEqual(run(output, [\"seed\"]), 0 if accepted else 1)
                    summary = json.loads((output / \"summary.json\").read_text())
                    self.assertEqual(summary[\"accepted\"], accepted)
